import { AxisScale } from '@visx/axis';
import { scaleBand, scaleLinear } from '@visx/scale';
import { AnyScaleBand } from '@visx/shape/lib/types';
import React from 'react';

export interface CategoricalChartScales {
  categoryScale: AnyScaleBand;
  valueScale: AxisScale<number>;
  dimensionScale: AnyScaleBand;
}
export const CategoricalBarChartScalesContext =
  React.createContext<CategoricalChartScales>({
    categoryScale: scaleBand(),
    valueScale: scaleLinear(),
    dimensionScale: scaleBand(),
  });
